(function() {
  // Only run once per element (use a flag)
  if (element.__reordered) return;
  element.__reordered = true;

  var children = Array.from(element.children);
  var russianItems = [];
  var englishItems = [];
  var otherItems = [];

  for (var i = 0; i < children.length; i++) {
    var child = children[i];
    // Only process organic serp-item results
    if (!child.classList.contains('serp-item')) {
      otherItems.push({ el: child, index: i });
      continue;
    }

    // Check if it has a translate link (indicates English content)
    var extralinksBtn = child.querySelector('.Organic-Extralinks');
    var isEnglish = false;
    if (extralinksBtn && extralinksBtn.getAttribute('data-vnl')) {
      try {
        var data = JSON.parse(extralinksBtn.getAttribute('data-vnl'));
        if (data.items) {
          for (var j = 0; j < data.items.length; j++) {
            if (data.items[j].variant === 'translate') {
              isEnglish = true;
              break;
            }
          }
        }
      } catch(e) {}
    }

    // Also check title text for Cyrillic
    if (!isEnglish) {
      var titleSpan = child.querySelector('.OrganicTitleContentSpan');
      if (titleSpan) {
        var titleText = titleSpan.textContent || '';
        // If title has no Cyrillic characters, it's likely English
        if (!/[\u0400-\u04FF]/.test(titleText)) {
          isEnglish = true;
        }
      }
    }

    if (isEnglish) {
      englishItems.push({ el: child, index: i });
    } else {
      russianItems.push({ el: child, index: i });
    }
  }

  // Rebuild order: russian first, then other (non-organic), then english at bottom
  var newOrder = [];
  // Collect items by original index to determine placement
  var allItems = [];
  for (var i = 0; i < children.length; i++) {
    allItems.push({ el: children[i], index: i });
  }

  // Sort: russian organic first, then non-organic in original order, then english organic at end
  var sortedItems = [];

  // First add russian items in their original relative order
  russianItems.forEach(function(item) {
    sortedItems.push(item);
  });

  // Then add non-organic items (like video carousel) in their original order
  otherItems.forEach(function(item) {
    sortedItems.push(item);
  });

  // Finally add english items at the bottom
  englishItems.forEach(function(item) {
    sortedItems.push(item);
  });

  // Now append in new order (appendChild moves existing nodes)
  for (var k = 0; k < sortedItems.length; k++) {
    element.appendChild(sortedItems[k].el);
  }
})();
